// Original low-resolution VFX atlases. Cached once; their world motion stays subpixel.
import {COLORS} from './art.mjs';
const TAU=Math.PI*2,cache=new Map(),N=64,FRAMES=12;
const clamp=(n,a=0,b=1)=>Math.max(a,Math.min(b,n)),noise=n=>{const v=Math.sin(n*127.1+311.7)*43758.5453;return v-Math.floor(v)};
function oval(c,x,y,rx,ry,color){c.fillStyle=color;for(let yy=-Math.ceil(ry);yy<=ry;yy++){const xx=Math.round(rx*Math.sqrt(Math.max(0,1-yy*yy/(ry*ry||1))));c.fillRect(Math.round(x)-xx,Math.round(y+yy),xx*2+1,1)}}
function poly(c,pts,color){c.fillStyle=color;c.beginPath();pts.forEach(([x,y],i)=>i?c.lineTo(Math.round(x),Math.round(y)):c.moveTo(Math.round(x),Math.round(y)));c.closePath();c.fill()}
function spriteFrame(c,kind,type,frame){const palette=COLORS[type]||COLORS.normal,[color,light,core]=palette,phase=frame/FRAMES*TAU;c.translate(32,32);
 if(kind==='flame'){
  const shape=(s,col)=>{const pts=[];for(let i=0;i<28;i++){const a=i/28*TAU,r=1+.18*Math.sin(a*5+phase)+.08*Math.sin(a*9-phase*2),x=Math.cos(a)*12*r,y=Math.sin(a)*12*r;pts.push([(x-(1-Math.cos(a))*7)*s,y*s])}poly(c,pts,col)};shape(1.12,'#6c302b');shape(1,color);shape(.74,light);shape(.4,core);for(let i=0;i<8;i++){const t=(i/8+frame/FRAMES)%1,x=-12-t*15,y=Math.sin(t*8+phase)*7*(1-t);oval(c,x,y,2.5*(1-t)+.6,2*(1-t)+.5,i%2?light:color)}
 }else if(kind==='orb'){
  const r=12+Math.sin(phase)*.7;oval(c,0,0,r+1,r+1,type==='grass'?'#275b37':type==='ghost'?'#38254d':'#29394e');oval(c,0,0,r,r,color);oval(c,-2,-2,r*.78,r*.78,light);oval(c,-4,-4,r*.4,r*.4,core);for(let j=0;j<3;j++){const pts=[];for(let i=0;i<13;i++){const a=i/12*Math.PI*1.4+phase+j*TAU/3;pts.push([Math.cos(a)*(r+2+j),Math.sin(a)*(r+2+j)*.7])}c.strokeStyle=j%2?light:color;c.lineWidth=2;c.beginPath();pts.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.stroke()}for(let i=0;i<4;i++){const a=phase+i*Math.PI/2;c.fillStyle=light;c.fillRect(Math.round(Math.cos(a)*19),Math.round(Math.sin(a)*19),2,2)}
 }else if(kind==='water'){
  poly(c,[[-20,0],[-9,-7],[5,-10],[14,-5],[17,0],[12,8],[0,9],[-10,5]],'#255885');poly(c,[[-17,0],[-6,-6],[7,-8],[14,-3],[14,4],[4,7],[-5,4]],color);poly(c,[[-9,-1],[0,-5],[9,-4],[12,0],[2,3]],light);c.fillStyle=core;c.fillRect(4,-4,5,2);for(let i=0;i<5;i++){const t=(i/5+frame/FRAMES)%1;oval(c,-12-t*12,Math.sin(phase+i)*8,2,1.5,light)}
 }else if(kind==='ice'){
  poly(c,[[-16,0],[-4,-7],[17,0],[-4,7]],'#376e94');poly(c,[[-14,0],[-4,-6],[15,0],[-4,6]],light);poly(c,[[-4,-5],[14,0],[-6,0]],core);poly(c,[[-13,1],[-5,1],[-3,5]],color);c.fillStyle='#e8ffff';c.fillRect(-16-frame%3*2,-8,2,2);c.fillRect(-11+frame%4,9,2,2);
 }else if(kind==='leaf'){
  poly(c,[[-12,4],[-8,-5],[2,-9],[13,-7],[7,5],[-4,9]],'#315531');poly(c,[[-11,4],[-6,-4],[3,-7],[11,-6],[6,4],[-4,7]],color);poly(c,[[-10,4],[9,-5],[0,5]],light);c.strokeStyle='#426536';c.lineWidth=1;c.beginPath();c.moveTo(-13,7);c.lineTo(8,-4);c.stroke();
 }else if(kind==='slash'){
  const pts=[],q=[];for(let i=0;i<20;i++){const a=-1.25+i/19*2.5;pts.push([Math.cos(a)*22-10,Math.sin(a)*22]);q.unshift([Math.cos(a)*(17-i*.2)-10,Math.sin(a)*(17-i*.2)])}poly(c,pts.concat(q),light);poly(c,pts.map(([x,y])=>[x-2,y]).concat(q),'#e9fbef');
 }else if(kind==='fangs'){
  const close=Math.sin(frame/(FRAMES-1)*Math.PI),gap=15-close*10;for(const sign of [-1,1]){const yy=sign*gap;poly(c,[[-20,yy-sign*8],[-12,yy-sign*11],[12,yy-sign*11],[20,yy-sign*8],[16,yy-sign*3],[-16,yy-sign*3]],'#3b3044');poly(c,[[-18,yy-sign*8],[-10,yy-sign*9],[10,yy-sign*9],[18,yy-sign*8],[14,yy-sign*4],[-14,yy-sign*4]],color);for(let i=0;i<4;i++){const x=-13+i*8;poly(c,[[x-3,yy-sign*5],[x+3,yy-sign*5],[x,yy+sign*6]],core)}}
 }else if(kind==='punch'){
  poly(c,[[-13,-10],[-8,-16],[9,-16],[17,-9],[17,8],[9,15],[-11,12],[-16,3]],'#4e3535');poly(c,[[-11,-9],[-7,-14],[8,-14],[15,-7],[15,7],[8,13],[-9,10],[-14,2]],color);for(let i=0;i<4;i++){c.fillStyle=light;c.fillRect(-8+i*5,-12,4,9)}c.fillStyle=core;c.fillRect(-7,-11,3,3);poly(c,[[-12,1],[-7,-2],[0,3],[-2,8],[-10,7]],light);
 }else if(kind==='smoke'){
  for(let i=0;i<5;i++){const a=i*2.399,r=5+frame*.6,x=Math.cos(a)*r,y=Math.sin(a)*r-frame*.6;oval(c,x,y,7+frame*.2,6+frame*.15,i%2?'#938b85':'#bcb49c')}for(let i=0;i<4;i++)oval(c,-4+i*3,-6,3,3,'#d9cfb4');
 }else if(kind==='impact'){
  const t=frame/(FRAMES-1),r=Math.sin(t*Math.PI)**.5*24;const shape=(scale,col)=>{const pts=[];for(let i=0;i<16;i++){const a=i*Math.PI/8,rr=r*(i%2?.35:1)*(i%4===0?1.15:1);pts.push([Math.cos(a)*rr*scale,Math.sin(a)*rr*scale])}poly(c,pts,col)};shape(1,color);shape(.7,light);shape(.35,core);for(let i=0;i<9;i++){const a=i*2.399,d=12+t*19;c.fillStyle=i%2?color:light;c.fillRect(Math.round(Math.cos(a)*d),Math.round(Math.sin(a)*d),2,2)}
 }else if(kind==='wave'){
  for(let y=-27;y<28;y++){const x=9*Math.cos(y/29)+Math.sin(y*.22+phase)*2;c.fillStyle='#255d98';c.fillRect(-19,y,Math.round(x+20),1);c.fillStyle=color;c.fillRect(-11,y,Math.round(x+12),1);c.fillStyle=light;c.fillRect(Math.round(x-4),y,5,1);c.fillStyle=core;c.fillRect(Math.round(x),y,3,1)}for(let i=0;i<10;i++){const yy=-24+i*5;c.fillStyle=i%2?core:light;c.fillRect(11+Math.sin(phase+i)*3,yy,2,2)}
 }else if(kind==='rock'){
 poly(c,[[-11,-4],[-6,-12],[6,-11],[13,-1],[8,11],[-6,10]],'#4b4544');poly(c,[[-10,-4],[-5,-10],[5,-9],[11,-1],[6,9],[-5,8]],color);poly(c,[[-8,-4],[-4,-8],[4,-7],[6,-3],[-1,0]],light);poly(c,[[1,1],[8,-1],[6,7],[-2,7]],'#73654e');
 }
}
function atlas(kind,type){const key=kind+':'+type;if(cache.has(key))return cache.get(key);const sheet=document.createElement('canvas');sheet.width=N*FRAMES;sheet.height=N;const ctx=sheet.getContext('2d');ctx.imageSmoothingEnabled=false;for(let i=0;i<FRAMES;i++){ctx.save();ctx.translate(i*N,0);spriteFrame(ctx,kind,type,i);ctx.restore()}cache.set(key,sheet);return sheet}
export function warmPixelFX(){for(const type of Object.keys(COLORS))for(const kind of ['impact','orb','slash','fangs','punch'])atlas(kind,type);for(const [kind,type]of [['flame','fire'],['orb','grass'],['orb','ghost'],['water','water'],['wave','water'],['ice','ice'],['leaf','grass'],['impact','normal'],['impact','fire'],['smoke','ground'],['slash','normal']])atlas(kind,type)}
export function drawPixel(c,kind,type,x,y,size,time=0,rotation=0,{once=false,alpha=1}={}){const sheet=atlas(kind,type),frame=once?Math.floor(clamp(time)*11):Math.floor(Math.max(0,time)*24)%FRAMES;c.save();c.globalAlpha*=alpha;c.imageSmoothingEnabled=false;c.translate(x,y);c.rotate(rotation);c.drawImage(sheet,frame*N,0,N,N,-size/2,-size/2,size,size);c.restore()}
export function drawCharge(c,move,at,t,{scale=1,reducedMotion=false}={}){if(t<0||t>1)return;const [color,light]=COLORS[move.type]||COLORS.normal,amount=reducedMotion?4:9;c.save();c.globalAlpha*=Math.sin(t*Math.PI)*.8;for(let i=0;i<amount;i++){const a=i*2.399+t*.7,r=(1-t)*25+5,x=at.x+Math.cos(a)*r*scale,y=at.y+Math.sin(a)*r*scale;c.fillStyle=i%2?color:light;c.fillRect(x-1,y-1,2*scale,2*scale)}drawPixel(c,move.type==='fire'?'flame':move.type==='water'?'water':'orb',move.type,at.x,at.y,(16+20*t)*scale,t);c.restore()}
export function drawImpact(c,move,at,t,{scale=1,reducedMotion=false}={}){if(t<0||t>1)return;const type=move.type||'normal';c.save();const fade=clamp((1-t)*2.5);drawPixel(c,'impact',type,at.x,at.y,95*scale,t,0,{once:true,alpha:fade});if(!reducedMotion)for(let i=0;i<8;i++){const a=i*2.399,r=14+54*t*t,x=at.x+Math.cos(a)*r*scale,y=at.y+Math.sin(a)*r*scale-t*10*scale;c.fillStyle=(COLORS[type]||COLORS.normal)[i%2];c.globalAlpha=fade*(1-t);c.fillRect(x,y,(3-i%2)*scale,(3-i%2)*scale)}c.restore()}
export function drawFlight(c,move,at,angle,time,{size=60,trail=1,reducedMotion=false}={}){
 const type=move.type||'normal',slug=move.slug||'',kind=type==='fire'?'flame':type==='water'?'water':type==='ice'?'ice':/leaf|razor/.test(slug)?'leaf':type==='rock'?'rock':'orb';
 const count=reducedMotion?2:6;for(let i=count;i>0;i--){const d=i*size*.15*trail,x=at.x-Math.cos(angle)*d,y=at.y-Math.sin(angle)*d;drawPixel(c,kind,type,x,y,size*(1-i/(count+2)),time-i*.025,kind==='leaf'?time*5+i:angle,{alpha:(1-i/(count+1))*.5})}drawPixel(c,kind,type,at.x,at.y,size,time,kind==='leaf'?time*6:angle);
}
export function drawStream(c,move,from,to,time,{width=28,reducedMotion=false,progress=1}={}){const dx=to.x-from.x,dy=to.y-from.y,length=Math.hypot(dx,dy)*clamp(progress),angle=Math.atan2(dy,dx),type=move.type||'normal',kind=type==='fire'?'flame':type==='water'?'water':type==='ice'?'ice':'orb';c.save();c.translate(from.x,from.y);c.rotate(angle);if(type==='fire'||type==='water'){
 const fire=type==='fire',palette=fire?['#81372c','#c34628','#f37d30','#ffd76c']:['#254e81','#287dbe','#56b8e4','#c9f8fa'];
 for(let x=0;x<length;x+=3){const q=x/(length||1),phase=x*.14-time*17,center=Math.sin(x*.05-time*13)*width*.13,r=width*(.22+q*.34)*(1+.18*Math.sin(phase));for(let layer=0;layer<4;layer++){const h=Math.max(1,r*[1,.85,.58,.22][layer]);c.fillStyle=palette[layer];c.fillRect(x,Math.round(center-h),4,Math.round(h*2))}}
 for(let i=0;i<(reducedMotion?7:19);i++){const q=(i/19+time*1.7)%1,x=q*length,y=Math.sin(i*2.399+time*4)*width*(.4+q*.4);c.fillStyle=palette[i%2+2];c.globalAlpha=(1-q)*.7;c.fillRect(x,y,fire?3:2,2)}c.globalAlpha=1;
 drawPixel(c,kind,type,length,0,width*(fire?2.8:2.2),time,0,{alpha:.95});
 }else{
 const palette=move.slug==='hyper-beam'?['#8f9bc9','#d9e9ff','#ffffff']:COLORS[type]||COLORS.normal;if(type!=='electric')for(let layer=0;layer<3;layer++){c.fillStyle=palette[layer];const h=width*[1,.65,.25][layer];c.fillRect(0,-h/2,length,h)}for(let i=0;i<(reducedMotion?5:17);i++){const q=(i/17+time*2)%1,x=q*length;c.fillStyle=palette[1];c.fillRect(x,Math.sin(i*2.399+time*5)*width,3,2)}if(type==='electric'){c.strokeStyle='#fff8b4';c.lineWidth=2;c.beginPath();for(let i=0;i<24;i++){const x=i/23*length,y=Math.sin(i*2.2+time*23)*width*.55;i?c.lineTo(x,y):c.moveTo(x,y)}c.stroke()}}
 c.restore();if(!['fire','water'].includes(type))drawPixel(c,'impact',type,to.x,to.y,width*2.1,time);}
export function drawWave(c,move,at,angle,time,{width=120,reducedMotion=false}={}){c.save();c.translate(at.x,at.y);c.rotate(angle);drawPixel(c,'wave','water',0,0,width*1.18,time);for(let i=0;i<(reducedMotion?3:11);i++){const phase=(time*2+i*.217)%1,x=-12-phase*52,y=Math.sin(i*2.399)*width*.39;c.globalAlpha=(1-phase)*.6;c.fillStyle=i%2?'#a8e8f0':'#509cc7';c.fillRect(x,y,4,3)}c.restore()}
